import{_ as e,o as a,c as n,a2 as l}from"./chunks/framework.ClgMjOt7.js";const u=JSON.parse('{"title":"ログインと認証メカニズム","description":"OAuth2 PKCE 認証フロー、トークン管理、暗号化保存、およびマルチアカウント構造","frontmatter":{"title":"ログインと認証メカニズム","description":"OAuth2 PKCE 認証フロー、トークン管理、暗号化保存、およびマルチアカウント構造"},"headers":[],"relativePath":"guide/authentication.md","filePath":"guide/authentication.md","lastUpdated":1786169627000}'),o={name:"guide/authentication.md"};function i(d,t,s,c,r,h){return a(),n("div",null,[...t[0]||(t[0]=[l(`<h1 id="ログインと認証メカニズム" tabindex="-1">ログインと認証メカニズム <a class="header-anchor" href="#ログインと認証メカニズム" aria-label="Permalink to &quot;ログインと認証メカニズム&quot;">​</a></h1><p>Palleria は Pixiv 公式の OAuth2 認証モデルを採用しています。認証情報は端末内のセキュアな領域に保護・保存されます。</p><hr><h2 id="認証アーキテクチャ" tabindex="-1">認証アーキテクチャ <a class="header-anchor" href="#認証アーキテクチャ" aria-label="Permalink to &quot;認証アーキテクチャ&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> [ ユーザー ] ──( ログイン要求 )──&gt; [ Custom Tabs / WebView ]</span></span>
<span class="line"><span>                                            │ (Pixiv ログイン画面)</span></span>
<span class="line"><span> [ Palleria アプリ ] &lt;──( pixiv:// リダイレクト )──┘</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├──&gt; [ Rust API クライアント (pixiv-api) ] ──( OAuth2 Exchange )──&gt; [ Pixiv Auth Server ]</span></span>
<span class="line"><span>        │                                                                           │</span></span>
<span class="line"><span>        └──&lt;───────────────────( Token / Refresh Token )───────────────────────────┘</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        └──&gt; [ KeyStore (AES-256-GCM) ] ──&gt; Room DB (AccountEntity)</span></span></code></pre></div><hr><h2 id="ログイン方式" tabindex="-1">ログイン方式 <a class="header-anchor" href="#ログイン方式" aria-label="Permalink to &quot;ログイン方式&quot;">​</a></h2><h3 id="_1-web-ログイン-標準" tabindex="-1">1. Web ログイン (標準) <a class="header-anchor" href="#_1-web-ログイン-標準" aria-label="Permalink to &quot;1. Web ログイン (標準)&quot;">​</a></h3><p>ブラウザコンポーネント（Custom Tabs または WebView）を経由して公式ログイン画面を呼び出し、認証コードを取得します。</p><ul><li><strong>リダイレクト URI</strong>: <code>pixiv://account/login</code></li><li><strong>PKCE (Proof Key for Code Exchange)</strong>: 認証リクエスト時にコードチャレンジャーを動的生成し、トークン交換時の安全性を確保。</li><li><strong>サードパーティ連携</strong>: Google, Apple, X (旧 Twitter) 経由でのシングルサインオンにも対応。</li></ul><hr><h2 id="_2-リフレッシュトークンログイン" tabindex="-1">2. リフレッシュトークンログイン <a class="header-anchor" href="#_2-リフレッシュトークンログイン" aria-label="Permalink to &quot;2. リフレッシュトークンログイン&quot;">​</a></h2><p>所持している Pixiv の <code>refresh_token</code> 文字列を直接入力してログインします。</p><ol><li>入力されたトークン文字列を受け取り、<code>RustPixivHttpClient</code> を通じて Pixiv 認証エンドポイント (<code>https://oauth.secure.pixiv.net/auth/token</code>) へリクエストを送信。</li><li>レスポンスとして新しい <code>access_token</code> と <code>refresh_token</code> を取得・検証後に保存。</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>refresh_token</code> はアカウント操作が可能な機密データです。第三者への共有やログへの記録にご注意ください。</p></div><hr><h2 id="トークンの安全な保存と自動更新" tabindex="-1">トークンの安全な保存と自動更新 <a class="header-anchor" href="#トークンの安全な保存と自動更新" aria-label="Permalink to &quot;トークンの安全な保存と自動更新&quot;">​</a></h2><ul><li><strong>暗号化保存</strong>: 取得された認証トークンは <code>EncryptedSharedPreferences</code> および <code>PallaSyncKeystore</code> を通じて <code>AndroidKeyStore</code> 内の AES-256-GCM マスターキーで暗号化され保存されます。</li><li><strong>トークン自動更新 (Refresh Token Rotation)</strong>: <code>access_token</code> の有効期限切れ（HTTP 400/401 エラー検知時）を検知すると、バックグラウンドで自動的に <code>refresh_token</code> を使用して新しいアクセストークンを再発行します。</li></ul><hr><h2 id="マルチアカウント管理構造" tabindex="-1">マルチアカウント管理構造 <a class="header-anchor" href="#マルチアカウント管理構造" aria-label="Permalink to &quot;マルチアカウント管理構造&quot;">​</a></h2><p>複数の Pixiv アカウントをアプリ内に保存・保持できます。</p><h3 id="データベース設計-accountentity" tabindex="-1">データベース設計 (<code>AccountEntity</code>) <a class="header-anchor" href="#データベース設計-accountentity" aria-label="Permalink to &quot;データベース設計 (\`AccountEntity\`)&quot;">​</a></h3><p>Room データベースの <code>AccountEntity</code> テーブルでアカウント状態を管理します。</p><table tabindex="0"><thead><tr><th style="text-align:left;">カラム名</th><th style="text-align:left;">型</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>userId</code></td><td style="text-align:left;"><code>Long</code> (PK)</td><td style="text-align:left;">Pixiv ユーザー ID</td></tr><tr><td style="text-align:left;"><code>name</code></td><td style="text-align:left;"><code>String</code></td><td style="text-align:left;">ユーザー表示名</td></tr><tr><td style="text-align:left;"><code>account</code></td><td style="text-align:left;"><code>String</code></td><td style="text-align:left;">アカウント ID (ログイン ID)</td></tr><tr><td style="text-align:left;"><code>profileImage</code></td><td style="text-align:left;"><code>String</code></td><td style="text-align:left;">アイコン画像 URL</td></tr><tr><td style="text-align:left;"><code>refreshToken</code></td><td style="text-align:left;"><code>String</code></td><td style="text-align:left;">暗号化保存されたリフレッシュトークン</td></tr><tr><td style="text-align:left;"><code>isPremium</code></td><td style="text-align:left;"><code>Boolean</code></td><td style="text-align:left;">プレミアム会員フラグ</td></tr><tr><td style="text-align:left;"><code>lastActiveAt</code></td><td style="text-align:left;"><code>Long</code></td><td style="text-align:left;">最終使用タイムスタンプ</td></tr></tbody></table><h3 id="アカウント切り替え" tabindex="-1">アカウント切り替え <a class="header-anchor" href="#アカウント切り替え" aria-label="Permalink to &quot;アカウント切り替え&quot;">​</a></h3><ul><li>アカウント切り替えシート (<code>AccountSwitchSheet</code>) からワンタップでアクティブアカウント (<code>activeAccountIndex</code>) を変更可能。</li><li>各アカウントの個別ログアウト、トークン再取得、プロファイル再同期をサポート。</li></ul>`,26)])])}const g=e(o,[["render",i]]);export{u as __pageData,g as default};
